// Loop over input items and add a new field called 'myNewField' to the JSON of each one

const rows = $input.all().map(i => i.json);

const issues = [];
const validRows = [];

// BLOCK 1: Read, clean and validate
for (let index = 0; index < rows.length; index++) {
  const row = rows[index];
  const rowNumber = index + 1;

  const rawAmount = row["Amount (KES)"] ?? row.Amount;
  const amount = parseFloat(
    String(rawAmount ?? "").replace(/[^0-9.\-]/g, "")
  );

  const type = String(row.Type ?? "").trim().toLowerCase();
  const dateText = String(row.Date ?? "").trim();
  const description = String(row.Description ?? "").trim();
  const categoryText = String(row.Category ?? "").trim();

  const parsedDate = new Date(dateText);
  const dateIsValid =
    dateText !== "" && !Number.isNaN(parsedDate.getTime());

  const rowIssues = [];

  if (rawAmount === undefined || rawAmount === null ||
      String(rawAmount).trim() === "" || !Number.isFinite(amount)) {
    rowIssues.push("Invalid Amount");
  }

  if (!["income", "expense"].includes(type)) {
    rowIssues.push("Type must be income or expense");
  }

  if (!dateIsValid) {
    rowIssues.push("Invalid Date");
  }

  if (rowIssues.length > 0) {
    issues.push({
      rowNumber,
      description,
      problems: rowIssues
    });
    continue;
  }

  // BLOCK 2: Auto-categorize if Category is empty
  let category = categoryText;

  if (!category) {
    const text = description.toLowerCase();

    const rules = [
      [/\brent\b|\blease\b/, "Rent"],
      [/\bwage\b|\bsalary\b|\bpayroll\b/, "Salaries"],
      [/\bfood\b|\bgrocer(?:y|ies)\b|\bsupermarket\b/, "Food"],
      [/\btransport\b|\bfuel\b|\btaxi\b|\bbus fare\b/, "Transport"],
      [/\belectricity\b|\bwater bill\b|\binternet\b|\butility\b/, "Utilities"],
      [/\bschool\b|\btuition\b|\bcourse fee\b/, "Education"],
      [/\bmedical\b|\bhospital\b|\bpharmacy\b|\bmedicine\b/, "Healthcare"],
      [/\bsale\b|\bsales\b|\bclient payment\b/, "Sales"],
      [/\binterest\b|\bdividend\b|\binvestment return\b/, "Investment Income"]
    ];

    const match = rules.find(([pattern]) => pattern.test(text));
    category = match ? match[1] : "Other";
  }

  validRows.push({
    rowNumber,
    date: parsedDate.toISOString().slice(0, 10),
    month: parsedDate.toISOString().slice(0, 7),
    type,
    amount,
    description,
    category
  });
}

// BLOCK 3: Calculate totals
const incomeRows = validRows.filter(r => r.type === "income");
const expenseRows = validRows.filter(r => r.type === "expense");

const totalIncome = incomeRows.reduce((sum, r) => sum + r.amount, 0);
const totalExpenses = expenseRows.reduce((sum, r) => sum + r.amount, 0);
const netSavings = totalIncome - totalExpenses;

const savingsRate = totalIncome !== 0
  ? (netSavings / totalIncome) * 100
  : null;

// BLOCK 4A: Expenses grouped by category
const categoryTotals = {};

for (const row of expenseRows) {
  categoryTotals[row.category] =
    (categoryTotals[row.category] || 0) + row.amount;
}

const expenseCategories = Object.entries(categoryTotals)
  .map(([name, amount]) => ({
    name,
    amount: Number(amount.toFixed(2)),
    pct: totalExpenses !== 0
      ? Number(((amount / totalExpenses) * 100).toFixed(2))
      : 0
  }))
  .sort((a, b) => b.amount - a.amount);

// BLOCK 4B: Daily income, expenses and cumulative savings
const dailyTotals = {};

for (const row of validRows) {
  if (!dailyTotals[row.date]) {
    dailyTotals[row.date] = { date: row.date, income: 0, expenses: 0 };
  }

  if (row.type === "income") {
    dailyTotals[row.date].income += row.amount;
  } else {
    dailyTotals[row.date].expenses += row.amount;
  }
}

let runningSavings = 0;

const dailySeries = Object.values(dailyTotals)
  .sort((a, b) => a.date.localeCompare(b.date))
  .map(day => {
    day.income = Number(day.income.toFixed(2));
    day.expenses = Number(day.expenses.toFixed(2));
    runningSavings += day.income - day.expenses;

    return {
      ...day,
      cumulativeSavings: Number(runningSavings.toFixed(2))
    };
  });

// BLOCK 4C: Biggest single expense
const biggestExpense = expenseRows.length
  ? expenseRows.reduce((biggest, row) =>
      row.amount > biggest.amount ? row : biggest
    )
  : null;

// BLOCK 4D: Month-over-month comparison
const monthlyTotals = {};

for (const row of validRows) {
  if (!monthlyTotals[row.month]) {
    monthlyTotals[row.month] = { month: row.month, income: 0, expenses: 0 };
  }

  if (row.type === "income") {
    monthlyTotals[row.month].income += row.amount;
  } else {
    monthlyTotals[row.month].expenses += row.amount;
  }
}

const monthlySeries = Object.values(monthlyTotals)
  .sort((a, b) => a.month.localeCompare(b.month));

const latestMonth = monthlySeries.length
  ? monthlySeries[monthlySeries.length - 1]
  : null;

const previousMonth = monthlySeries.length >= 2
  ? monthlySeries[monthlySeries.length - 2]
  : null;

function percentChange(current, previous) {
  if (previous === 0) return current === 0 ? 0 : null;
  return Number((((current - previous) / Math.abs(previous)) * 100).toFixed(2));
}

const monthOverMonth = latestMonth
  ? {
      latestMonth: latestMonth.month,
      previousMonth: previousMonth?.month ?? null,
      incomeChangePct: previousMonth
        ? percentChange(latestMonth.income, previousMonth.income)
        : null,
      expensesChangePct: previousMonth
        ? percentChange(latestMonth.expenses, previousMonth.expenses)
        : null,
      savingsChangePct: previousMonth
        ? percentChange(
            latestMonth.income - latestMonth.expenses,
            previousMonth.income - previousMonth.expenses
          )
        : null
    }
  : null;

const chartColors = {
  pink: "#E0B4AE",
  peach: "#F2CC9E",
  teal: "#BCD5D8"
};

// CHART 1: Daily income vs expenses
const incomeExpenseConfig = {
  type: "bar",
  data: {
    labels: dailySeries.map(d => d.date),
    datasets: [
      {
        label: "Income",
        data: dailySeries.map(d => d.income),
        backgroundColor: chartColors.pink
      },
      {
        label: "Expenses",
        data: dailySeries.map(d => d.expenses),
        backgroundColor: chartColors.peach
      }
    ]
  },
  options: {
    title: {
      display: true,
      text: "Daily Income vs Expenses"
    },
    legend: {
      position: "top"
    },
    scales: {
      yAxes: [{
        ticks: { beginAtZero: true }
      }]
    }
  }
};

// CHART 2: Expense category breakdown
const expenseCategoryConfig = {
  type: "doughnut",
  data: {
    labels: expenseCategories.map(
      c => `${c.name} (${c.pct}%)`
    ),
    datasets: [{
      data: expenseCategories.map(c => c.amount),
      backgroundColor: expenseCategories.map(
        (_, i) => [
          chartColors.pink,
          chartColors.peach,
          chartColors.teal
        ][i % 3]
      )
    }]
  },
  options: {
    title: {
      display: true,
      text: "Expense Breakdown by Category"
    },
    legend: {
      position: "right"
    }
  }
};

// CHART 3: Cumulative savings
const cumulativeSavingsConfig = {
  type: "bar",
  data: {
    labels: dailySeries.map(d => d.date),
    datasets: [{
      label: "Cumulative Savings",
      data: dailySeries.map(d => d.cumulativeSavings),
      backgroundColor: chartColors.teal
    }]
  },
  options: {
    title: {
      display: true,
      text: "Cumulative Savings Over Time"
    },
    legend: {
      display: true
    },
    scales: {
      yAxes: [{
        ticks: {
          beginAtZero: true
        }
      }]
    }
  }
};

// Convert each Chart.js configuration to a QuickChart URL
function makeChartUrl(config) {
  return "https://quickchart.io/chart?w=640&h=340&bkg=white&c="
    + encodeURIComponent(JSON.stringify(config));
}

const chartUrls = {
  incomeVsExpenses: makeChartUrl(incomeExpenseConfig),
  expenseBreakdown: makeChartUrl(expenseCategoryConfig),
  cumulativeSavings: makeChartUrl(cumulativeSavingsConfig)
};

const financialSummary = {
  totalIncome,
  totalExpenses,
  netSavings,
  savingsRate:
    savingsRate === null
      ? null
      : Number(savingsRate.toFixed(2)),
  expenseCategories,
  biggestExpense,
  monthOverMonth
};

const aiPrompt = `
You are a helpful personal finance analyst.

Use ONLY the numbers and information in the JSON below.
Do not invent figures, causes, transactions, or financial facts.
If a value is missing or null, say it is unavailable rather than guessing.
Write for a non-accountant using clear, simple language.
Keep the entire response under approximately 180 words.

Return the explanation using exactly these sections:

Summary
Briefly explain total income, total expenses, net savings,
and savings rate where available.

Where the money went
Identify the largest expense categories using the supplied
category amounts and percentages. Mention the biggest single
expense if that information is available.

3 Recommended actions
Give exactly three practical, specific actions supported by
the supplied numbers. Do not make assumptions about the user's
circumstances.

Financial data:
${JSON.stringify(financialSummary, null, 2)}
`;

return [{
  json: {
    rowCount: rows.length,
    chartUrls,
    aiPrompt,
    validRowCount: validRows.length,
    invalidRowCount: issues.length,
    issues,
    totalIncome: Number(totalIncome.toFixed(2)),
    totalExpenses: Number(totalExpenses.toFixed(2)),
    netSavings: Number(netSavings.toFixed(2)),
    savingsRate: savingsRate === null ? null : Number(savingsRate.toFixed(2)),
    expenseCategories,
    dailySeries,
    biggestExpense: biggestExpense
      ? {
          date: biggestExpense.date,
          description: biggestExpense.description,
          category: biggestExpense.category,
          amount: biggestExpense.amount
        }
      : null,
    monthlySeries,
    monthOverMonth
  }
}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one

const metrics = $('Calculate Metrics').first().json;
const gemini = $input.first().json;

// ---------- Helpers ----------
function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function money(value) {
  if (value === null || value === undefined || value === "") {
    return "N/A";
  }

  return "KES " + Number(value).toLocaleString("en-KE", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function safeImageUrl(url) {
  return typeof url === "string" && /^https:\/\/quickchart\.io\//i.test(url)
    ? escapeHtml(url)
    : "";
}

// ---------- Get Gemini's explanation ----------
const aiText =
  gemini.candidates?.[0]?.content?.parts
    ?.map(part => part.text || "")
    .join("\n")
  || "The AI explanation is unavailable. Please check the Gemini Analysis node.";

// Convert simple Markdown into email-safe HTML.
function markdownToHtml(text) {
  const lines = text.split(/\r?\n/);
  const output = [];
  let inList = false;

  function closeList() {
    if (inList) {
      output.push("</ul>");
      inList = false;
    }
  }

  for (const line of lines) {
    const trimmed = line.trim();

    if (!trimmed) {
      closeList();
      continue;
    }

    if (trimmed.startsWith("## ")) {
      closeList();
      output.push(
        `<h3 style="color:#334155;font-size:17px;margin:18px 0 8px;">${escapeHtml(trimmed.slice(3))}</h3>`
      );
    } else if (trimmed.startsWith("# ")) {
      closeList();
      output.push(
        `<h3 style="color:#334155;font-size:17px;margin:18px 0 8px;">${escapeHtml(trimmed.slice(2))}</h3>`
      );
    } else if (trimmed.startsWith("- ") || trimmed.startsWith("* ")) {
      if (!inList) {
        output.push(
          '<ul style="padding-left:22px;margin:8px 0;line-height:1.6;">'
        );
        inList = true;
      }

      output.push(`<li>${escapeHtml(trimmed.slice(2))}</li>`);
    } else {
      closeList();
      output.push(
        `<p style="margin:8px 0;line-height:1.6;color:#334155;">${escapeHtml(trimmed)}</p>`
      );
    }
  }

  closeList();
  return output.join("\n");
}

// ---------- KPI values ----------
const totalIncome = Number(metrics.totalIncome ?? 0);
const totalExpenses = Number(metrics.totalExpenses ?? 0);
const netSavings = Number(metrics.netSavings ?? 0);
const savingsRate = metrics.savingsRate;

const categories = Array.isArray(metrics.expenseCategories)
  ? metrics.expenseCategories
  : [];

const chartUrls = metrics.chartUrls || {};

const categoryColors = ["#E0B4AE", "#F2CC9E", "#BCD5D8"];

// ---------- Category table ----------
const categoryRows = categories.length
  ? categories.map((category, index) => {
      const pct = Math.max(0, Math.min(100, Number(category.pct) || 0));
      const color = categoryColors[index % categoryColors.length];

      return `
        <tr>
          <td style="padding:10px;border-bottom:1px solid #eeeeee;color:#334155;">
            ${escapeHtml(category.name)}
          </td>
          <td style="padding:10px;text-align:right;border-bottom:1px solid #eeeeee;white-space:nowrap;">
            ${money(category.amount)}
          </td>
          <td style="padding:10px;border-bottom:1px solid #eeeeee;width:35%;">
            <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">
              <tr>
                <td width="${pct}%" bgcolor="${color}" height="12"
                    style="font-size:0;line-height:0;">&nbsp;</td>
                <td style="font-size:0;line-height:0;">&nbsp;</td>
              </tr>
            </table>
            <div style="font-size:12px;color:#64748b;margin-top:4px;">${pct.toFixed(2)}%</div>
          </td>
        </tr>
      `;
    }).join("")
  : `<tr><td colspan="3" style="padding:12px;">No expense categories available.</td></tr>`;

// ---------- Chart images ----------
function chartImage(url, alt) {
  const safeUrl = safeImageUrl(url);

  if (!safeUrl) {
    return `<p style="color:#64748b;">${escapeHtml(alt)}: chart unavailable.</p>`;
  }

  return `
    <tr>
      <td align="center" style="padding:12px 0;">
        <img src="${safeUrl}" width="600" alt="${escapeHtml(alt)}"
             style="display:block;width:100%;max-width:600px;height:auto;border:0;">
      </td>
    </tr>
  `;
}

// ---------- Assemble the email ----------
const html = `
<!DOCTYPE html>
<html>
<body style="margin:0;padding:0;background:#f4f7fb;font-family:Arial,Helvetica,sans-serif;color:#334155;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f7fb;">
    <tr>
      <td align="center" style="padding:20px 10px;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
               style="max-width:680px;background:#ffffff;border:1px solid #e5e7eb;">

          <tr>
            <td bgcolor="#BCD5D8" style="padding:24px;text-align:center;">
              <h1 style="margin:0;font-size:24px;color:#243746;">Financial Summary Report</h1>
              <p style="margin:8px 0 0;font-size:13px;color:#334155;">
                Generated ${escapeHtml(new Date().toISOString().slice(0, 10))}
              </p>
            </td>
          </tr>

          <tr>
            <td style="padding:20px;">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
                     style="border-collapse:collapse;">
                <tr>
                  <td bgcolor="#D9EAD3" width="48%" style="padding:15px;font-weight:bold;color:#24532a;">
                    Total income
                  </td>
                  <td width="52%" style="padding:15px;border:1px solid #e5e7eb;font-weight:bold;">
                    ${money(totalIncome)}
                  </td>
                </tr>
                <tr>
                  <td bgcolor="#F4CCCC" style="padding:15px;font-weight:bold;color:#8a3030;">
                    Total expenses
                  </td>
                  <td style="padding:15px;border:1px solid #e5e7eb;font-weight:bold;">
                    ${money(totalExpenses)}
                  </td>
                </tr>
                <tr>
                  <td bgcolor="#BCD5D8" style="padding:15px;font-weight:bold;color:#243746;">
                    Total savings
                  </td>
                  <td style="padding:15px;border:1px solid #e5e7eb;font-weight:bold;">
                    ${money(netSavings)}
                  </td>
                </tr>
              </table>

              <p style="font-size:13px;color:#64748b;margin:12px 0 0;">
                Savings rate: ${savingsRate == null ? "N/A" : escapeHtml(Number(savingsRate).toFixed(2) + "%")}
              </p>

              <h2 style="font-size:19px;margin:28px 0 8px;color:#243746;">Your charts</h2>
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
                ${chartImage(chartUrls.incomeVsExpenses, "Daily income versus expenses")}
                ${chartImage(chartUrls.expenseBreakdown, "Expense category breakdown")}
                ${chartImage(chartUrls.cumulativeSavings, "Cumulative savings")}
              </table>

              <h2 style="font-size:19px;margin:24px 0 8px;color:#243746;">Where the money went</h2>
              <table width="100%" cellpadding="0" cellspacing="0" border="0"
                     style="border-collapse:collapse;font-size:13px;">
                <tr bgcolor="#f1f5f9">
                  <th align="left" style="padding:10px;">Category</th>
                  <th align="right" style="padding:10px;">Amount</th>
                  <th align="left" style="padding:10px;">Share</th>
                </tr>
                ${categoryRows}
              </table>

              <h2 style="font-size:19px;margin:28px 0 8px;color:#243746;">Financial explanation and recommendations</h2>
              ${markdownToHtml(aiText)}
            </td>
          </tr>

          <tr>
            <td bgcolor="#f1f5f9" style="padding:16px;text-align:center;font-size:12px;color:#64748b;">
              Automatically generated financial report
            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>
</body>
</html>
`;

// ---------- Email subject and log-sheet summary ----------
const subject =
  `Financial Summary - ${new Date().toISOString().slice(0, 10)}`;

const summaryRow = {
  generatedAt: new Date().toISOString(),
  totalIncome,
  totalExpenses,
  netSavings,
  savingsRate,
  categoryCount: categories.length,
  biggestExpense: metrics.biggestExpense?.amount ?? null,
  aiSummary: aiText.slice(0, 500),
  reportSubject: subject
};

return [{
  json: {
    subject,
    html,
    summaryRow
  }
}];
